// Extrai informações do documento PDF recebido via Telegram.
// Suporta mensagens diretas ao bot e mensagens em grupos.
const msg = $input.first().json?.message || $input.first().json?.channel_post || {};
const chatId   = msg?.chat?.id || '';
const doc      = msg?.document || null;
const caption  = msg?.caption || '';

if (!doc) {
  return [{ json: { ignorar: true, motivo: 'Mensagem sem documento', chatId } }];
}

const mime = doc.mime_type || '';
if (!mime.includes('pdf')) {
  return [{ json: { ignorar: true, motivo: 'Arquivo não é PDF', chatId } }];
}

// Extrair mês da legenda, se informado
const mMap = {
  'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março',
  'abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho',
  'agosto':'Agosto','setembro':'Setembro','outubro':'Outubro',
  'novembro':'Novembro','dezembro':'Dezembro'
};
const captionLower = caption.toLowerCase();
const mesCaption = Object.entries(mMap).find(([k]) => captionLower.includes(k))?.[1] || '';

return [{ json: {
  ignorar:   false,
  fileId:    doc.file_id,
  fileName:  doc.file_name || 'fatura.pdf',
  chatId,
  mesCaption,
  caption
} }];

